<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, nextTick, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import client from '../api/client'
import AppIcon from '../components/AppIcon.vue'
import NavigationSearch from '../components/NavigationSearch.vue'
import BrandLogo from '../components/BrandLogo.vue'
import ThemeToggle from '../components/ThemeToggle.vue'
import { theme } from '../stores/theme'
import { loadSystemSettings, systemSettings } from '../stores/systemSettings'
const route=useRoute(),router=useRouter(),collapsed=ref(localStorage.getItem('menu_collapsed')==='1'||window.innerWidth<800)
const mobile=ref(window.innerWidth<800), searchOpen=ref(false), compact=ref(localStorage.getItem('ui_density')==='compact')
const navigationItems=computed(()=>groups.value.flatMap(group=>group.items.map(item=>({path:item[0],title:item[1],group:group.title}))))
function toggleDensity(){compact.value=!compact.value;localStorage.setItem('ui_density',compact.value?'compact':'comfortable')}
function resize(){const next=window.innerWidth<800;if(next!==mobile.value){mobile.value=next;if(next)collapsed.value=true}}
function shortcut(event:KeyboardEvent){if(event.key==='Escape'&&mobile.value)collapsed.value=true;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchOpen.value=!searchOpen.value}}
function navigate(path:string){router.push(path)}
watch(()=>route.fullPath,async()=>{if(mobile.value)collapsed.value=true;await nextTick();document.getElementById('main-content')?.focus({preventScroll:true})})
onMounted(()=>{window.addEventListener('resize',resize);window.addEventListener('keydown',shortcut)})
onBeforeUnmount(()=>{window.removeEventListener('resize',resize);window.removeEventListener('keydown',shortcut)})
const appVersion=__APP_VERSION__
const account=ref<any>({username:'',permissions:[]})
const allGroups=[
  {title:'监控中心',icon:'monitor',permission:'monitor.view',items:[['/','监控总览'],['/monitor-wall','监控大屏'],['/monitors','探测任务'],['/monitor-results','探测结果'],['/chains','业务链路']]},
  {title:'资产管理',icon:'assets',permission:'asset.view',items:[['/businesses','业务系统'],['/business-groups','业务分组'],['/tags','标签管理']]},
  {title:'事件与告警',icon:'alert',permission:'alert.view',items:[['/incidents','故障事件'],['/rules','告警规则'],['/channels','通知渠道'],['/notifications','发送记录']]},
  {title:'维护与报表',icon:'report',permission:'report.view',items:[['/maintenance','维护窗口'],['/sla','SLA 报表'],['/status-pages','状态页']]},
  {title:'组织与权限',icon:'organization',permission:'iam.view',items:[['/users','用户管理'],['/departments','部门管理'],['/roles','角色管理']]},
  {title:'系统管理',icon:'settings',permission:'system.view',items:[['/system-settings','系统设置'],['/login-records','登录记录'],['/audit','审计日志'],['/system-health','系统健康']]},
]
const groups=computed(()=>allGroups.filter(g=>account.value.is_superuser||(account.value.permissions||[]).includes(g.permission)))
const currentTitle=computed(()=>route.params.monitorId?'任务历史数据':groups.value.flatMap(g=>g.items).find(i=>i[0]===route.path)?.[1]||'监控总览')
const activeGroup=computed(()=>String(Math.max(0,groups.value.findIndex(group=>group.items.some(item=>item[0]===route.path)))))
function toggle(){collapsed.value=!collapsed.value;localStorage.setItem('menu_collapsed',collapsed.value?'1':'0')}
async function logout(){const refresh=localStorage.getItem('refresh_token');try{if(refresh)await client.post('/auth/logout/',{refresh})}finally{localStorage.removeItem('access_token');localStorage.removeItem('refresh_token');router.push('/login')}}
onMounted(async()=>{const [me]=await Promise.allSettled([client.get('/auth/me/'),loadSystemSettings()]);if(me.status==='fulfilled')account.value=me.value.data;window.setTimeout(()=>{import('./MonitorWallView.vue').catch(()=>undefined)},500)})
</script>
<template><el-container class="app-shell" :class="{'is-compact':compact,'is-mobile':mobile}"><a class="skip-link" href="#main-content">跳到主要内容</a><button v-if="mobile&&!collapsed" class="menu-backdrop" aria-label="关闭导航菜单" @click="collapsed=true"></button><el-aside v-show="!mobile||!collapsed" :width="mobile?(collapsed?'0px':'248px'):(collapsed?'72px':'248px')" class="sidebar"><div class="brand"><BrandLogo :theme="theme" :compact="collapsed" :text="systemSettings.brand_logo_text"/></div><el-menu router unique-opened @select="mobile&&(collapsed=true)" :collapse="collapsed" :collapse-transition="false" :default-active="route.params.monitorId?'/monitors':$route.path" :default-openeds="[activeGroup]"><el-sub-menu v-for="(group,index) in groups" :key="group.title" :index="String(index)"><template #title><span class="menu-icon"><AppIcon :name="group.icon"/></span><span class="group-title">{{group.title}}</span></template><el-menu-item v-for="item in group.items" :key="item[0]" :index="item[0]"><span class="item-line"></span><template #title>{{item[1]}}</template></el-menu-item></el-sub-menu></el-menu><a v-show="!collapsed" class="api-docs" href="/api/v1/docs/" target="_blank">开发者 API 文档 <span>↗</span></a></el-aside><el-container class="workspace" :style="{marginLeft:mobile?'0px':collapsed?'72px':'248px'}"><el-header class="topbar"><div class="topbar-left"><button class="collapse-button" :aria-expanded="!collapsed" :aria-label="collapsed?'展开菜单':'折叠菜单'" :title="collapsed?'展开菜单':'折叠菜单'" @click="toggle"><span></span><span></span><span></span></button><div class="breadcrumb" aria-label="当前位置"><span>{{groups[Number(activeGroup)]?.title||'HELI MONITOR'}}</span><i>/</i><b>{{currentTitle}}</b></div></div><div class="topbar-right"><ThemeToggle/><button class="quick-search-button" title="搜索页面（Ctrl / ⌘ + K）" @click="searchOpen=true"><span>搜索页面</span><kbd>⌘ / Ctrl K</kbd></button><button class="density-button" :aria-pressed="compact" :title="compact?'切换为舒适间距':'切换为紧凑间距'" @click="toggleDensity">{{compact?'紧凑':'舒适'}}</button><span class="app-version" title="当前应用版本">{{appVersion}}</span><div class="avatar">{{(account.username||'用').slice(0,1).toUpperCase()}}</div><div class="account"><b>{{[account.last_name,account.first_name].filter(Boolean).join('')||account.username||'当前用户'}}</b><span>{{account.department_name||'未分配部门'}}</span></div><el-button text @click="logout">退出</el-button></div></el-header><el-main id="main-content" tabindex="-1"><div class="content-wrap"><router-view/></div></el-main></el-container><NavigationSearch v-model="searchOpen" :items="navigationItems" @navigate="navigate"/></el-container></template>
