t:700}.account{display:flex;flex-direction:column;line-height:1.3;max-width:110px}.account b{font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.account span{font-size:10px;color:var(--muted);margin-top:2px}.el-main{background:var(--canvas);padding:0;overflow:visible;min-width:0;flex:1}.content-wrap{width:100%;max-width:1800px;margin:auto;padding:30px 32px 48px}.menu-backdrop{position:fixed;inset:0;border:0;background:#091a3466;z-index:19}.skip-link{position:fixed;left:16px;top:-80px;z-index:3000;padding:12px 18px;background:var(--surface);color:var(--brand);border-radius:8px;border:1px solid var(--brand)}.skip-link:focus{top:12px}#main-content:focus{outline:none}
